    rows = []
    for i in range(count):
        rows.append(
            "{ts: new Date(Date.now() - %d * 60000).toISOString(), seven_day_pct: %d,"
            " seven_day_resets_at: new Date(Date.now() + %d * 3600000).toISOString(),"
            " providers: null}" % (first_age_min - 30 * i, 20 + i, reset_in_h)
        )
